(function(){
'use strict';
const Q=AUDDiagnostic.data,R=AUDReview,$r=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let reviews={},ready=false,canReview=false,limit=40,current=null,history=[];
const states={nao_revisado:'Não revisado',confirmed:'Confirmado no GT',pending:'Pendente',rejected:'Enquadramento rejeitado',reverted:'Decisão revertida',conflito:'Fonte alterada — conferir decisão'};
function catalogKey(kind){return Q.catalogo[kind]?kind:Object.keys(Q.catalogo).find(k=>kind?.startsWith(k))||''}
function info(kind){const key=catalogKey(kind),c=Q.catalogo[key];$r('catalog-title').textContent=c?.nome_oficial||kind||'Enquadramento a esclarecer';$r('catalog-content').innerHTML=c?'<p>'+h(c.definicao)+'</p><p><strong>Escopo:</strong> '+h(c.escopo)+'</p><p><strong>Subtipos:</strong> '+h(c.subtipos.join('; ')||'Sem subdivisão adicional documentada neste catálogo')+'</p><p>'+h(c.caracteristicas)+'</p><p><strong>Exemplos de apoio:</strong> '+h(c.exemplos.join('; ')||'Consultar o verbete e as evidências do produto.')+'</p><p><strong>Cuidados:</strong> '+h(c.nao_incluir_automaticamente)+'</p><p><strong>Evidências recomendadas:</strong> '+h(c.evidencias_recomendadas)+'</p><p>'+h(c.natureza_descricao)+'</p><p>'+h(c.localizacao)+'</p><ul>'+c.fontes.map(k=>'<li><a href="'+h(Q.fontes[k].url)+'" target="_blank" rel="noopener">'+h(Q.fontes[k].titulo)+'</a> — '+h(Q.fontes[k].localizacao)+'</li>').join('')+'</ul>':'<p>Este rótulo é uma hipótese operacional de enquadramento. Abra a revisão e consulte o catálogo para escolher um tipo documentado. A classificação exige evidências de natureza, autoria e aderência.</p>';$r('catalog-dialog').showModal()}
for(const [group,label]of [['bibliografica','Bibliográfica'],['tecnica','Técnica/tecnológica'],['artistica','Artístico-cultural']]){const opt=document.createElement('optgroup');opt.label=label;for(const [key,c]of Object.entries(Q.catalogo)){if(c.grupo!==group)continue;const o=document.createElement('option');o.value=key;o.textContent=key+(c.escopo==='lista_geral_nao_equiparada'?' — lista geral':'');opt.append(o)}$r('review-kind').append(opt)}
const blank=document.createElement('option');blank.value='';blank.textContent='Escolha o tipo de enquadramento';$r('review-kind').prepend(blank);
function onAnalysis(a){if($r('review-panel').hidden)return;const text=$r('review-search').value.toLocaleLowerCase('pt-BR'),filter=$r('review-filter').value;
 const items=[...new Map(a.details.map(p=>[p.produto_id,Q.produtos.find(x=>x.produto_id===p.produto_id)])).values()].filter(p=>(!text||[p.titulo_original,p.referencia_original,...p.participacoes.map(x=>x.docente)].join(' ').toLocaleLowerCase('pt-BR').includes(text))&&(filter==='all'||R.status(p,reviews[p.produto_id])===filter));
 $r('review-count').textContent=items.length+' produto(s) únicos no recorte da análise; mostrando '+Math.min(limit,items.length)+'. A busca e o filtro de revisão se aplicam a esta lista.';
 $r('review-list').innerHTML=items.slice(0,limit).map(p=>'<article class="review-item"><div><div class="eyebrow">'+h(p.participacoes.map(x=>x.docente).join('; '))+' · '+h(p.ano)+'</div><strong>'+h(p.titulo_original||p.referencia_original)+'</strong><p>'+h(p.estado)+' · '+h(p.tipo_capes)+' <button class="info-button" data-catalog="'+h(p.tipo_capes)+'" aria-label="Explicar categoria">ⓘ</button></p><p>'+h(states[R.status(p,reviews[p.produto_id])])+'</p></div><button data-review="'+h(p.produto_id)+'" '+(!ready?'disabled':'')+'>Revisar produto</button></article>').join('')||'<p>Nenhum produto neste recorte.</p>';
 $r('review-more').hidden=items.length<=limit;
 const orphans=Object.values(reviews).filter(r=>r.action!=='reverted'&&!Q.produtos.some(p=>p.produto_id===r.product_id));$r('review-orphans').hidden=!orphans.length;$r('review-orphans').textContent=orphans.length?orphans.length+' decisão(ões) preservada(s) sem correspondência na base atual. Podem se referir a registros alterados ou removidos; não são aplicadas automaticamente. Consulte o backup com histórico. Produtos: '+orphans.map(r=>r.source_snapshot?.titulo||r.product_id).join('; '):'';
}
function renderHistory(){const r=reviews[current.produto_id],events=history.filter(x=>x.product_id===current.produto_id);$r('review-history').innerHTML='<p>'+h(r?'Última decisão: '+(states[r.action]||r.action)+' · versão '+r.revision+' · '+new Date(r.updated_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Nenhuma decisão humana salva para este produto.')+'</p>'+events.map(e=>{const v=JSON.parse(e.payload);return '<p><strong>Versão '+h(e.revision)+' — '+h(states[v.action])+'</strong><br>'+h(v.notes)+'<br>'+h(v.kind)+' · '+h(e.created_at)+'</p>'}).join('')}
async function open(id){current=Q.produtos.find(p=>p.produto_id===id);if(!current)return;const r=reviews[id],key=r?.kind||catalogKey(current.tipo_capes)||Object.keys(Q.catalogo).find(k=>Q.catalogo[k].tipo_bibliografico===current.tipo_bibliografico)||'';
 $r('review-source').innerHTML='<h3>'+h(current.titulo_original||'Conferir referência')+'</h3><p>'+h(current.participacoes.map(x=>x.docente).join('; '))+' · '+h(current.ano)+'</p><div class="review-auto"><strong>Sugestão automática preservada</strong><p>'+h(current.estado)+' · '+h(current.grande_categoria)+' · '+h(current.tipo_capes)+'</p><p>'+h(current.justificativa)+'</p><p><strong>Outras hipóteses:</strong> '+h(current.enquadramento_alternativo||'Sem alternativa definida; consulte o catálogo.')+'</p><p><strong>Evidências examinadas:</strong> '+h(JSON.stringify(current.evidencias_avaliadas||{}))+'</p></div><details open><summary>Registros originais e fontes</summary>'+current.registros_origem.map(x=>'<p>'+h(x.docente)+' · '+h(x.categoria_lattes)+' / '+h(x.subcategoria_lattes)+'<br>'+h(x.referencia_original)+'<br><a href="https://lattes.cnpq.br/'+h(x.docente_id)+'" target="_blank" rel="noopener">Consultar Lattes ↗</a></p>').join('')+'</details><p>'+h(states[R.status(current,r)])+'</p>';
 $r('review-kind').value=key;$r('review-action').value=r&&r.action!=='reverted'?r.action:'confirmed';$r('review-notes').value=r?.notes||'';$r('review-evidence').value=r?.evidence||'';$r('review-save-status').textContent=ready?(canReview?'As alterações só serão aplicadas após salvar.':'Entre com a conta do responsável para alterar as decisões. A consulta está disponível.'):'Armazenamento indisponível; consulta permitida, salvamento desativado.';$r('review-save').disabled=!ready||!canReview;renderHistory();$r('review-dialog').showModal();
 try{const result=await fetch('/api/reviews?history=1',{cache:'no-store'});if(result.ok){const data=await result.json();history=data.history||[];if(current?.produto_id===id)renderHistory()}}catch{}
}
document.addEventListener('click',event=>{const b=event.target.closest('[data-review],[data-catalog],[data-close]');if(!b)return;if(b.dataset.review)open(b.dataset.review);else if(b.dataset.catalog!==undefined)info(b.dataset.catalog);else if(b.dataset.close)$r(b.dataset.close).close()});
$r('review-info').onclick=()=>info($r('review-kind').value);
$r('review-toggle').onclick=()=>{$r('review-panel').hidden=!$r('review-panel').hidden;$r('review-toggle').textContent=$r('review-panel').hidden?'Abrir revisão de produções':'Fechar lista de revisão';onAnalysis(AUDDiagnostic.analysis())};
for(const id of ['review-search','review-filter'])$r(id).addEventListener(id==='review-search'?'input':'change',()=>{limit=40;onAnalysis(AUDDiagnostic.analysis())});$r('review-more').onclick=()=>{limit+=50;onAnalysis(AUDDiagnostic.analysis())};
$r('review-form').onsubmit=async event=>{event.preventDefault();if(!ready||!canReview||!current)return;const kind=$r('review-kind').value,category=Q.catalogo[kind]?.grupo;if(!category){$r('review-save-status').textContent='Escolha um tipo do catálogo.';return}const payload={product_id:current.produto_id,action:$r('review-action').value,category,kind,notes:$r('review-notes').value,evidence:$r('review-evidence').value,source_signature:R.signature(current),expected_revision:reviews[current.produto_id]?.revision||0};$r('review-save').disabled=true;$r('review-save-status').textContent='Salvando…';try{const res=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await res.json();if(!res.ok)throw Error(data.error||'Falha ao salvar');reviews[current.produto_id]=data.review;AUDDiagnostic.refresh();$r('review-save-status').textContent='Decisão salva no servidor. Use “Com decisões do GT” ou “Somente confirmadas pelo GT” para aplicar à contagem.';renderHistory()}catch(e){$r('review-save-status').textContent=e.message+' A sugestão automática foi preservada.'}finally{$r('review-save').disabled=!ready||!canReview}};
async function backup(){if(self!==top){const url=new URL(location.href);url.search='?view=qualified&reviewExport=backup';window.open(url,'_blank','noopener');return}try{const r=await fetch('/api/reviews?history=1',{cache:'no-store'});if(!r.ok)throw Error('Não foi possível baixar as decisões');download(new Blob([JSON.stringify({exportado_em:new Date().toISOString(),versao_regras:Q.versao_regras,...await r.json()},null,2)],{type:'application/json'}),'revisoes-gt-e-historico.json')}catch(e){$r('review-storage').textContent=e.message}}
$r('review-backup').onclick=backup;
window.AtlasReview={dataset:(data,mode)=>R.dataset(data,reviews,mode),onAnalysis,open,info,ready:()=>ready,reviews:()=>reviews};
fetch('/api/reviews',{cache:'no-store'}).then(async r=>{if(!r.ok)throw Error();const data=await r.json();reviews=data.reviews||{};canReview=data.can_review===true;ready=true;$r('qa-mode').disabled=false;$r('review-storage').textContent=Object.values(reviews).filter(r=>r.action!=='reverted').length+' decisão(ões) ativa(s) salva(s) no servidor. Sugestões assistidas anteriores não são decisões humanas.'+(canReview?'':' Entre com a conta do responsável para revisar.');AUDDiagnostic.refresh();window.dispatchEvent(new Event('atlas:reviews-ready'));if(new URLSearchParams(location.search).get('reviewExport')==='backup')backup()}).catch(()=>{$r('review-storage').textContent='Não foi possível carregar o armazenamento de revisões. A análise automática está disponível; não considere uma decisão salva até receber confirmação do servidor.';onAnalysis(AUDDiagnostic.analysis())});
})();
